import { ChartBinItem } from '@/types/dlmm'
import { Token } from '@cetus/types'
import { bnToAmount, d, formatNumberWithDown, formatPriceWithDown, formatTickPrice, removeComma } from '@cetus/utils'
import { BinAmount, BinUtils } from 'dd_dlmm_sdk'
import { getRates } from './clmm'
import { getReversePrice } from './pool'

export const getRelatedDisplayPrice = (price: string) => {
  const displayPrice = price === '∞' ? '∞' : formatTickPrice(price, 6) + ''
  const reversePrice = getReversePrice(price) + ''
  const displayReversePrice = reversePrice === '∞' ? '∞' : formatTickPrice(reversePrice, 6) + ''
  return [displayPrice, reversePrice, displayReversePrice]
}

export const formatBinPriceFromLamport = (priceLamport: string, baseDecimal: number, quoteDecimal: number) => {
  return String(formatPriceWithDown(BinUtils.getPriceFromLamport(baseDecimal, quoteDecimal, priceLamport)))
}

export const formatPriceFromBin = (bin: number, binStep: number, baseDecimal: number, quoteDecimal: number) => {
  return String(formatPriceWithDown(BinUtils.getPriceFromBinId(bin, binStep, baseDecimal, quoteDecimal)))
}

export const formatBinList = (
  bins: BinAmount[],
  baseToken: Token,
  quoteToken: Token,
  direct = true,
  activeBin?: number,
  binStep?: number
): {
  list: ChartBinItem[]
  max: number
} => {
  let max = 0
  const noRadius = bins?.length > 150
  const baseDecimal = baseToken?.decimals
  const quoteDecimal = quoteToken?.decimals
  const res = bins?.map((item: BinAmount) => {
    const liquidity = d(item?.liquidity)?.div(Math.pow(10, 10)).toNumber()
    const price = removeComma(formatBinPriceFromLamport(item.price_per_lamport, baseDecimal, quoteDecimal))
    const baseAmount = bnToAmount(item?.amount_a, baseDecimal)
    const quoteAmount = bnToAmount(item?.amount_b, quoteDecimal)
    let quantityA
    let quantityB
    if (item?.bin_id === activeBin) {
      const total = d(baseAmount).mul(price).add(quoteAmount)
      quantityA = d(baseAmount).mul(price).div(total).toString()
      quantityB = d(quoteAmount).div(total).toString()
    }

    max = Math.max(max, liquidity)
    return {
      ...item,
      liquidity,
      price: formatNumberWithDown(direct || direct === undefined ? price : d(1).div(price).toString(), 6),
      baseSymbol: baseToken?.symbol,
      quoteSymbol: quoteToken?.symbol,
      baseAmount,
      quoteAmount,
      quantityA,
      quantityB,
      noRadius
    }
  })

  if (activeBin !== undefined && binStep !== undefined && res?.[0]?.bin_id > activeBin) {
    const price = removeComma(formatPriceFromBin(activeBin, binStep, baseDecimal, quoteDecimal))
    res.unshift({
      // ...sortList?.[0],
      bin_id: activeBin,
      price: formatNumberWithDown(direct || direct === undefined ? price : d(1).div(price).toString(), 6),
      liquidity: undefined
    })
  }

  if (activeBin !== undefined && binStep !== undefined && res?.[res?.length - 1]?.bin_id < activeBin) {
    const price = removeComma(formatPriceFromBin(activeBin, binStep, baseDecimal, quoteDecimal))
    res.push({
      // ...sortList?.[sortList?.length - 1],
      bin_id: activeBin,
      price: formatNumberWithDown(direct || direct === undefined ? price : d(1).div(price).toString(), 6),
      liquidity: undefined
    })
  }

  const sortList = res.sort((a, b) => a?.price - b?.price)
  return {
    list: [...sortList],
    max: d(max).toNumber()
  }
}

